function validate([nums, key, k]) {
  if (nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value in nums is an integer from 1 to 1000.';
  if (!nums.includes(key)) return 'key must occur in nums.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is between 1 and nums.length.';
  return null;
}

