function findKDistantIndices(nums, key, k) {
  const result = [];
  let next = 0;

  for (let j = 0; j < nums.length; j++) {
    if (nums[j] !== key) {
      continue;
    }
    const start = Math.max(next, j - k);
    const end = Math.min(nums.length - 1, j + k);
    for (let i = start; i <= end; i++) {
      result.push(i);
    }
    next = end + 1;
  }
  return result;
}

