function findKDistantIndices(nums, key, k) {
  const out = [];
  for (let i = 0; i < nums.length; i++) {
    let near = false;
    for (let j = 0; j < nums.length; j++) if (nums[j] === key && Math.abs(i - j) <= k) near = true;
    if (near) out.push(i);
  }
  return out;
}

