function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1000 : 1 + Math.floor(rand() * 10);
  const span = large ? (rand() < 0.5 ? 1000 : 30) : 1 + Math.floor(rand() * 4);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * span));
  const key = nums[Math.floor(rand() * n)];
  const k = large && rand() < 0.7 ? 1 + Math.floor(rand() * 20) : 1 + Math.floor(rand() * n);
  return [nums, key, k];
}
